"""ZIP/TAR output helpers for ouch-compatible compression."""
import bz2
import gzip
import lzma
import os
import tarfile
import zipfile


def _members(paths):
    """Yield (source path, archive path) in stable traversal order."""
    for src in paths:
        src = os.fspath(src)
        name = os.path.basename(os.path.normpath(src)) or src
        if os.path.isdir(src):
            yield src, name
            for root, dirs, files in os.walk(src):
                dirs.sort()
                files.sort()
                relroot = os.path.relpath(root, os.path.dirname(os.path.normpath(src)) or ".")
                for d in dirs:
                    full = os.path.join(root, d)
                    rel = os.path.relpath(full, os.path.dirname(os.path.normpath(src)) or ".")
                    yield full, rel
                for f in files:
                    full = os.path.join(root, f)
                    rel = os.path.relpath(full, os.path.dirname(os.path.normpath(src)) or ".")
                    yield full, rel
        else:
            yield src, name


def compress(inputs, output, formats=None, level=None, follow_symlinks=False):
    """Create ZIP/TAR and optional stream layers. Returns output path.

    ``formats`` are ordered inner-to-outer, e.g. ["tar", "gz"].
    """
    formats = [str(x).lower().lstrip(".") for x in (formats or [])]
    aliases = {"tgz": ["tar", "gz"], "tbz": ["tar", "bz2"],
               "tbz2": ["tar", "bz2"], "txz": ["tar", "xz"],
               "tlzma": ["tar", "lzma"], "tzst": ["tar", "zst"],
               "tlz": ["tar", "lz"], "tlz4": ["tar", "lz4"],
               "tsz": ["tar", "sz"], "cbz": ["zip"], "epub": ["zip"],
               "cb7": ["7z"]}
    if len(formats) == 1 and formats[0] in aliases:
        formats = aliases[formats[0]]
    if not formats:
        raise ValueError("compression format required")
    if formats[0] not in ("zip", "tar"):
        if formats[0] in ("gz", "bz", "bz2", "xz", "lzma") and len(inputs) == 1:
            source = os.fspath(inputs[0])
            level = 9 if level is None else max(0, min(9, int(level)))
            with open(source, "rb") as inp, open(output, "wb") as raw:
                if formats[0] == "gz":
                    with gzip.GzipFile(filename="", mode="wb", compresslevel=max(1, level), fileobj=raw, mtime=0) as enc:
                        _copy(inp, enc)
                elif formats[0] in ("bz", "bz2"):
                    raw.write(bz2.compress(inp.read(), compresslevel=max(1, min(9, level))))
                elif formats[0] in ("xz", "lzma"):
                    raw.write(lzma.compress(inp.read(), preset=max(0, min(9, level))))
            return output
        raise ValueError("unsupported compression format")
    if formats[0] == "zip":
        comp = zipfile.ZIP_DEFLATED
        with zipfile.ZipFile(output, "w", comp, compresslevel=level) as zf:
            for src, arc in _members(inputs):
                if os.path.isdir(src):
                    zf.write(src, arc.rstrip("/") + "/")
                elif follow_symlinks or not os.path.islink(src):
                    zf.write(src, arc)
    else:
        mode = "w"
        tar_name = output
        outer = formats[1:]
        # Build tar in memory before applying stream compression layers.
        import io
        buf = io.BytesIO()
        with tarfile.open(fileobj=buf, mode="w", format=tarfile.PAX_FORMAT) as tf:
            for src, arc in _members(inputs):
                if os.path.islink(src) and not follow_symlinks:
                    tf.add(src, arcname=arc, recursive=False)
                else:
                    tf.add(src, arcname=arc, recursive=False)
        data = buf.getvalue()
        for fmt in outer:
            if fmt == "gz":
                data = gzip.compress(data, compresslevel=9 if level is None else max(1, min(9, int(level))), mtime=0)
            elif fmt in ("bz", "bz2"):
                data = bz2.compress(data, compresslevel=9 if level is None else max(1, min(9, int(level))))
            elif fmt in ("xz", "lzma"):
                data = lzma.compress(data, preset=9 if level is None else max(0, min(9, int(level))))
            else:
                raise ValueError("unsupported compression format")
        with open(tar_name, "wb") as f:
            f.write(data)
    return output


def _copy(source, target):
    while True:
        chunk = source.read(1024 * 1024)
        if not chunk:
            break
        target.write(chunk)

